mapper.select:
SELECT * FROM ( -- 定数包效期监控 SELECT l.label_id AS labelId, NULL AS batchId, 1 AS stockType, l.material_id AS materialId, m.material_name AS materialName, m.specification, l.warehouse_id AS warehouseId, w.node_name AS warehouseName, b.batch_no AS batchNo, b.production_date AS productionDate, b.expiry_date AS expiryDate, DATEDIFF(b.expiry_date, CURDATE()) AS remainingDays, CASE WHEN DATEDIFF(b.expiry_date, CURDATE()) < 0 THEN 4 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 30 THEN 1 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 60 THEN 2 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 90 THEN 3 ELSE 0 END AS warningLevel, l.package_num AS stockQuantity, s.supplier_name AS supplierName, l.create_time AS createTime FROM spd_label l LEFT JOIN spd_material_batch b ON l.batch_id = b.batch_id LEFT JOIN spd_material m ON l.material_id = m.material_id LEFT JOIN spd_org_node w ON l.warehouse_id = w.node_id LEFT JOIN spd_supplier s ON b.supplier_id = s.supplier_id WHERE l.del_flag = 0 AND l.label_status = 1 AND b.expiry_date IS NOT NULL
UNION ALL
-- 散货效期监控 SELECT NULL AS labelId, bm.id AS batchId, 2 AS stockType, bm.material_id AS materialId, m.material_name AS materialName, m.specification, bm.warehouse_id AS warehouseId, w.node_name AS warehouseName, b.batch_no AS batchNo, b.production_date AS productionDate, b.expiry_date AS expiryDate, DATEDIFF(b.expiry_date, CURDATE()) AS remainingDays, CASE WHEN DATEDIFF(b.expiry_date, CURDATE()) < 0 THEN 4 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 30 THEN 1 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 60 THEN 2 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 90 THEN 3 ELSE 0 END AS warningLevel, bm.remaining_num AS stockQuantity, s.supplier_name AS supplierName, bm.create_time AS createTime FROM spd_bulk_material bm LEFT JOIN spd_material_batch b ON bm.batch_id = b.batch_id LEFT JOIN spd_material m ON bm.material_id = m.material_id LEFT JOIN spd_org_node w ON bm.warehouse_id = w.node_id LEFT JOIN spd_supplier s ON b.supplier_id = s.supplier_id WHERE bm.del_flag = 0 AND bm.remaining_num > 0 AND b.expiry_date IS NOT NULL ) AS combined_data WHERE 1=1
AND materialName LIKE CONCAT('%', #{query.materialName}, '%')
AND warehouseId = #{query.warehouseId}
AND stockType = #{query.stockType}
AND warningLevel = #{query.warningLevel}
AND batchNo LIKE CONCAT('%', #{query.batchNo}, '%')
ORDER BY warningLevel DESC, remainingDays ASC

SELECT * FROM ( -- 定数包效期监控 SELECT l.label_id AS labelId, NULL AS batchId, 1 AS stockType, l.material_id AS materialId, m.material_name AS materialName, m.specification, l.warehouse_id AS warehouseId, w.node_name AS warehouseName, b.batch_no AS batchNo, b.production_date AS productionDate, b.expiry_date AS expiryDate, DATEDIFF(b.expiry_date, CURDATE()) AS remainingDays, CASE WHEN DATEDIFF(b.expiry_date, CURDATE()) < 0 THEN 4 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 30 THEN 1 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 60 THEN 2 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 90 THEN 3 ELSE 0 END AS warningLevel, l.package_num AS stockQuantity, s.supplier_name AS supplierName, l.create_time AS createTime FROM spd_label l LEFT JOIN spd_material_batch b ON l.batch_id = b.batch_id LEFT JOIN spd_material m ON l.material_id = m.material_id LEFT JOIN spd_org_node w ON l.warehouse_id = w.node_id LEFT JOIN spd_supplier s ON b.supplier_id = s.supplier_id WHERE l.del_flag = 0 AND l.label_status = 1 AND b.expiry_date IS NOT NULL AND DATEDIFF(b.expiry_date, CURDATE()) <= #{days}
UNION ALL
-- 散货效期监控 SELECT NULL AS labelId, bm.id AS batchId, 2 AS stockType, bm.material_id AS materialId, m.material_name AS materialName, m.specification, bm.warehouse_id AS warehouseId, w.node_name AS warehouseName, b.batch_no AS batchNo, b.production_date AS productionDate, b.expiry_date AS expiryDate, DATEDIFF(b.expiry_date, CURDATE()) AS remainingDays, CASE WHEN DATEDIFF(b.expiry_date, CURDATE()) < 0 THEN 4 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 30 THEN 1 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 60 THEN 2 WHEN DATEDIFF(b.expiry_date, CURDATE()) <= 90 THEN 3 ELSE 0 END AS warningLevel, bm.remaining_num AS stockQuantity, s.supplier_name AS supplierName, bm.create_time AS createTime FROM spd_bulk_material bm LEFT JOIN spd_material_batch b ON bm.batch_id = b.batch_id LEFT JOIN spd_material m ON bm.material_id = m.material_id LEFT JOIN spd_org_node w ON bm.warehouse_id = w.node_id LEFT JOIN spd_supplier s ON b.supplier_id = s.supplier_id WHERE bm.del_flag = 0 AND bm.remaining_num > 0 AND b.expiry_date IS NOT NULL AND DATEDIFF(b.expiry_date, CURDATE()) <= #{days} ) AS combined_data ORDER BY remainingDays ASC LIMIT 100
